#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> arr(n), pge(n, -1);
    for (int i = 0; i < n; i++)
        cin >> arr[i];

    stack<int> st;

    for (int i = 0; i < n; i++) {
        while (!st.empty() && st.top() <= arr[i])
            st.pop();

        if (!st.empty())
            pge[i] = st.top();

        st.push(arr[i]);
    }

    for (int x : pge)
        cout << x << ' ';

    return 0;
}
